(this.webpackJsonppcodesdev=this.webpackJsonppcodesdev||[]).push([[17],{191:function(e){e.exports=JSON.parse('[{"id":"home-positioning","title":"Professional Profile","url":"/#/home","content":"Peter Njuguna is a Digital Transformation & Technology Solutions Professional. I connect project management, AI engineering and implementation, and technology delivery across digital transformation, EdTech and learning, workforce development, and practical software solutions. Core areas: Project Management, AI Engineering & Implementation, EdTech & Digital Learning, Digital Skills & Workforce Development, Full-Stack Development, Cloud Solutions."},{"id":"about-biography","title":"About and Professional Background","url":"/#/about","content":"I am a Digital Transformation & Technology Solutions professional with a BSc in Information and Communication Technology from Laikipia University. My experience spans digital skills programme delivery, technology implementation, software development, and digital learning initiatives. At Finn Church Aid Kenya, I progressed from programme support to Project Officer \u2013 Digital Skills. I coordinate schedules, trainers, partners, learning resources, and day-to-day implementation across Nairobi, Kakuma, and Dadaab. I monitor attendance, learner progress, follow-up, programme records, and reporting. I bring project coordination, AI engineering and implementation, and technical delivery together across digital skills programmes, technology-enabled learning, software development, digital transformation, and workforce development."},{"id":"project-management-expertise","title":"Project Management Expertise","url":"/#/expertise","content":"Project planning and implementation; workplan development and scheduling; stakeholder, partner, team, and trainer coordination; monitoring, evaluation, and reporting; risk identification and mitigation; resource coordination; deliverable and milestone tracking. At FCA Kenya I coordinate programme schedules, trainers, partners, learning-hub operations, learner follow-up, progress monitoring, and reporting. As Project Officer I coordinate and supervise 12+ trainers, facilitators, and consultants and support annual bootcamps reaching 1,800+ secondary learners."},{"id":"ai-engineering-expertise","title":"AI Engineering & Implementation","url":"/#/expertise","content":"AI Engineering; AI Implementation & Integration; AI-Assisted Software Development; AI-Powered Workflow Automation; AI Solutions Development; AI Applications in EdTech & Digital Learning. AI tools listed separately include ChatGPT/OpenAI, Google Gemini, Claude, Microsoft Copilot, GitHub Copilot, and Perplexity."},{"id":"technology-languages","title":"Programming Languages","url":"/#/expertise","content":"Portfolio-listed languages and web foundations include Java, JavaScript, HTML5, CSS3, Python, PHP, SQL, and TypeScript."},{"id":"technology-frameworks","title":"Frameworks and Web Libraries","url":"/#/expertise","content":"Portfolio-listed frameworks and libraries include React, Next.js, Node.js, Django, Tailwind CSS, Dexie, IndexedDB, and SheetJS. Pemanju Farm Manager is described as using React, TypeScript, Vite, Tailwind CSS, Dexie, IndexedDB, and SheetJS."},{"id":"technology-databases","title":"Databases and Data Technologies","url":"/#/expertise","content":"Portfolio-listed data technologies include MySQL, MongoDB, PostgreSQL, Firebase, SQL, Dexie, and IndexedDB. Supabase/PostgreSQL synchronization for Pemanju Farm Manager is planned, not deployed."},{"id":"technology-cloud","title":"Cloud and Infrastructure Technologies","url":"/#/expertise","content":"Cloud and deployment tools shown in the portfolio include Google Cloud, Amazon Web Services, Vercel, and GitHub Actions. Cloud capability is described as foundational; cloud sync for Pemanju Farm Manager is planned."},{"id":"technology-operating-systems","title":"Operating Systems","url":"/#/expertise","content":"The technology inventory lists Windows, Linux, Ubuntu, macOS, Android, and iOS. Desktop/server and mobile systems are grouped separately on Expertise."},{"id":"project-delivery-methods","title":"Project Management Methods and Tools","url":"/#/expertise","content":"Project management competencies include planning, implementation, workplans, schedules, tasks, milestones, team coordination, stakeholder management, monitoring, evaluation, and reporting. Listed tools include Trello, Jira, Asana, Notion, Microsoft Teams, and Slack. Tools are separate from professional competencies."},{"id":"learning-platforms","title":"Digital Skills Training and EdTech Tools","url":"/#/expertise","content":"Digital skills training competencies include technical facilitation, learning management systems, e-learning, blended learning, digital learning content, and STEM/digital-skills education. Listed learning tools include Moodle and Google Classroom; other existing portfolio learning tools include Microsoft Teams, Canva, and Zoom."},{"id":"design-productivity-tools","title":"Design, Collaboration, and Productivity Tools","url":"/#/expertise","content":"The portfolio technology inventory lists Figma, Adobe XD, Adobe Creative Cloud, Canva, Google Workspace, Microsoft 365, Zoom, Slack, Notion, Replit, and GitHub."},{"id":"edtech-expertise","title":"EdTech & Digital Learning Expertise","url":"/#/expertise","content":"Learning-hub operations, technology-resource coordination, digital training schedules, learning materials, LMS support, blended learning, assessments, learner exercises, trainer and partner coordination, and learner support in technology-enabled learning environments. The remote-area EdTech concept is planning-stage only and is not an implemented or deployed platform."},{"id":"digital-skills-expertise","title":"Digital Skills & Workforce Development","url":"/#/expertise","content":"Digital skills programme delivery connects training, learner development, and employability-oriented pathways. Capabilities include training coordination, trainer engagement, partner coordination, learner support, programme implementation, records, monitoring, and reporting."},{"id":"full-stack-expertise","title":"Full-Stack Development Expertise","url":"/#/expertise","content":"React, TypeScript, JavaScript interfaces, application logic, data modelling, relational integrity, offline-first persistence with Dexie and IndexedDB, Excel import/export, and data validation workflows. Pemanju Farm Manager is an offline-first livestock records application shaped around field conditions and spreadsheet workflows."},{"id":"data-systems-expertise","title":"Data Systems Expertise","url":"/#/expertise","content":"Data collection system design, record validation, automated quality checks, anomaly-detection approaches, data cleaning, analysis, governance, audit readiness, and process automation for reporting. At Realfield Limited, designed systems processing 500,000+ records at 99.7% accuracy and pipelines reducing manual verification time by 80%."},{"id":"cloud-expertise","title":"Cloud Solutions Expertise","url":"/#/expertise","content":"Cloud computing and architecture fundamentals, deployment concepts, service reliability, IT support, troubleshooting, and security/access-control fundamentals. Supabase/PostgreSQL synchronization for Pemanju Farm Manager remains planned, not deployed."},{"id":"experience-project-officer","title":"Project Officer \u2013 Digital Skills at Finn Church Aid Kenya","url":"/#/experience","content":"December 2024 \u2013 Present, Kakuma & Dadaab, Kenya. Coordinate implementation workplans, onboarding, training schedules, attendance, mentorship, learner progress, follow-up, learning resources, assessments, programme data, reports, and UNICEF, Ajira Digital, UNHCR, DRC, government, private-sector, and community partners. Achievements stated in the portfolio: 500+ refugee and host-community youth supported in training; approximately 70% women and girls; bootcamps reaching 1,800+ secondary learners annually; coordinate and supervise 12+ trainers, facilitators, and consultants; reported 50% placement success in this role."},{"id":"experience-project-assistant","title":"Project Assistant / Digital Skills Trainer at Finn Church Aid","url":"/#/experience","content":"January 2022 \u2013 November 2024, Nairobi & Kakuma, Kenya. Delivered hands-on digital literacy and ICT training across graphic design, illustration, 3D animation, motion design, web development, and digital marketing. Supported session planning, blended delivery, LMS use, assignment tracking, onboarding, mentorship, career readiness, portfolios, learner follow-up, and ICT troubleshooting. Portfolio-stated achievements: 600+ learners trained and a separate reported 60% placement success rate for this role."},{"id":"experience-realfield","title":"Data Specialist at Realfield Limited","url":"/#/experience","content":"March 2021 \u2013 December 2021, Nakuru, Kenya (Remote). Collected, cleaned, validated, and analyzed data; implemented machine-learning approaches for anomaly detection; supported data governance and audit readiness. Portfolio-stated achievements: systems processing 500,000+ records with 99.7% accuracy and validation pipelines reducing manual verification time by 80%."},{"id":"experience-kplc","title":"ICT Technical Associate at Kenya Power and Lighting Company","url":"/#/experience","content":"January 2021 \u2013 March 2021, Nakuru, Kenya. Developed technical documentation, user guides, presentations, and training materials; delivered structured technical workshops and collaborated with IT teams. Portfolio-stated achievements: trained 50+ non-technical staff and improved digital-tool adoption by 30% through targeted training and support."},{"id":"experience-pemanju","title":"Full-Stack Developer at Pemanju IT Consulting Services","url":"/#/experience","content":"May 2018 \u2013 Present, Nairobi, Kenya. Designs and develops web-based solutions around usability, data integrity, and operational workflows. Pemanju Farm Manager applies offline-first design and structured records to farm operations."},{"id":"project-pemanju-farm-manager","title":"Pemanju Farm Manager Case Study","url":"/#/projects","content":"Offline-first livestock management application designed to improve record keeping, animal traceability, and farm operations. Addresses fragmented spreadsheets/manual notes and inconsistent identifiers. My role: Full-Stack Developer at Pemanju IT Consulting Services. Implemented technologies stated in the portfolio: React, TypeScript, Vite, Tailwind CSS, Dexie, IndexedDB, SheetJS, relational record model, and spreadsheet import/export. Supabase/PostgreSQL synchronization and expanded deployment are planned, not deployed. The public portfolio does not currently link a verified source repository/demo or project-specific evidence artifact."},{"id":"project-edumetrics","title":"EduMetrics","url":"/#/projects","externalUrl":"https://github.com/pcodesdev/EduMetrics","content":"Student performance analytics platform. Imports assessment files, normalizes data, and produces class insights and printable reports. Stack listed: Python, FastAPI, pandas, React, Vite, Tailwind CSS, Recharts. The project card links to its GitHub repository."},{"id":"project-react-movie-app","title":"React Movie App","url":"/#/projects","externalUrl":"https://github.com/pcodesdev/react-movie-app","content":"Movie discovery sample integrating TMDB search and Appwrite-backed search analytics. Stack listed: React, Vite, Tailwind CSS, Appwrite, and TMDB API. Use case: explore movie information and trending searches."},{"id":"project-weather-app","title":"Weather Forecast and History","url":"/#/projects","externalUrl":"https://github.com/pcodesdev/weather-app","content":"WeatherAPI sample presenting current conditions, a three-day forecast, and four days of historical data. Engineering focus listed: server-side API-key handling and combining current, forecast, and historical responses."},{"id":"project-movie-watch-list","title":"Movie Watch List","url":"/#/projects","externalUrl":"https://github.com/pcodesdev/Movie-Watch-List","content":"Browser-based movie search and watchlist app using the OMDb API and local storage. Search for movies, inspect details, and save titles to a personal watchlist."},{"id":"project-cart-menu","title":"Cart-Menu","url":"/#/projects","externalUrl":"https://github.com/pcodesdev/menu-cart","content":"Restaurant menu and cart demo with item selection, order totals, and simulated checkout. Engineering focus: client-side cart state, total calculation, input validation, and responsive presentation."},{"id":"project-task-list","title":"Task List","url":"/#/projects","externalUrl":"https://github.com/pcodesdev/task-list","content":"Interactive React task-list app with task creation, completion, deletion, sorting, and responsive UI behavior."},{"id":"education-degree","title":"BSc Information and Communication Technology","url":"/#/education","externalUrl":"https://laikipia.ac.ke/","content":"Laikipia University. BSc in Information and Communication Technology, 2016\u20132020. Listed academic topics include software development, programming, databases, data analysis, networking, cybersecurity, cloud computing, DevOps, and emerging technologies."},{"id":"education-scrimba","title":"Scrimba Frontend Developer Career Path","url":"/#/education","externalUrl":"https://v2.scrimba.com/the-frontend-developer-career-path-c0j:details","content":"Completed in 2024. Course topics include React, JavaScript, HTML, CSS, Git/GitHub, accessibility fundamentals, responsive layouts, and component-based interfaces."},{"id":"education-certifications","title":"Certifications and Professional Learning","url":"/#/education","content":"Portfolio-listed credentials include freeCodeCamp Responsive Web Design; JavaScript Algorithms and Data Structures; HackerRank Frontend Developer (React); Google IT Support; Google Cloud Digital Leader; AWS Cloud Practitioner; and Training of Trainers (Tallinn University). See the Education page for issuer links."},{"id":"opensource-profile","title":"Open Source Contributions","url":"/#/opensource","externalUrl":"https://github.com/pcodesdev","content":"The Open Source page shows a cached public GitHub REST snapshot for verified account pcodesdev. Pull requests and issues are filtered by author login; repository stars and forks count only repositories owned by the account. Issue search may return fewer rows than its reported total. The contribution calendar is unavailable without authenticated GraphQL access."},{"id":"github-profile-statistics","title":"GitHub Profile Statistics for pcodesdev","url":"/#/opensource","externalUrl":"https://github.com/pcodesdev","domain":"open-source","content":"Public GitHub REST API retrieved 2026-11-05. Verified profile login pcodesdev, account ID 44283776. Profile reports 307 public repositories. Across repositories owned by pcodesdev, 30 stars and 6 forks were returned. Author-filtered REST search matched 6 pull requests: 3 merged and 3 open. Author-filtered issue search matched 14 issues: 10 closed and 4 open; the search returned 12 issue records for display. GitHub commit author search matched 731 commits; this is not the GitHub contribution-calendar total. Authenticated GraphQL contribution calendar was unavailable in this retrieval. Snapshot status cached; refresh date and API state are shown on the Open Source page."},{"id":"github-pr-golclinics-dsa-clinics24-83","title":"Pull request: DSA-Clinics24 #83","url":"/#/opensource","externalUrl":"https://github.com/golclinics/DSA-Clinics24/pull/83","domain":"open-source","content":"Authored by pcodesdev. Open pull request created 2024-10-10 in golclinics/DSA-Clinics24. One file changed, 34 additions, zero deletions."},{"id":"github-pr-zero-to-mastery-resources-989","title":"Pull request: Update CONTRIBUTORS.md #989","url":"/#/opensource","externalUrl":"https://github.com/zero-to-mastery/resources/pull/989","domain":"open-source","content":"Authored by pcodesdev. Merged pull request in zero-to-mastery/resources, created 2024-09-12 and merged 2024-09-15. One file changed, one addition."},{"id":"github-pr-zero-to-mastery-resources-987","title":"Pull request: Product management and design podcast category #987","url":"/#/opensource","externalUrl":"https://github.com/zero-to-mastery/resources/pull/987","domain":"open-source","content":"Authored by pcodesdev. Merged pull request in zero-to-mastery/resources, created 2024-09-12 and merged 2024-09-15. One file changed, 11 additions and 10 deletions."},{"id":"github-pr-ashutosh1919-masterportfolio-384","title":"Pull request: Responsiveness and accessibility CSS updates #384","url":"/#/opensource","externalUrl":"https://github.com/ashutosh1919/masterPortfolio/pull/384","domain":"open-source","content":"Authored by pcodesdev. Open pull request in ashutosh1919/masterPortfolio, created 2024-08-24. GitHub API reports 1,726 changed files, 185,854 additions, and 610 deletions; verify the unusual changed-file size before using it as a portfolio claim."},{"id":"github-pr-mosh-hamedani-vidly-mvc-5-368","title":"Pull request: Add video times to README #368","url":"/#/opensource","externalUrl":"https://github.com/mosh-hamedani/vidly-mvc-5/pull/368","domain":"open-source","content":"Authored by pcodesdev. Open pull request in mosh-hamedani/vidly-mvc-5, created 2023-05-07. One file changed, one addition and two deletions."},{"id":"github-pr-pcodesdev-git-and-github-1","title":"Pull request: Git-and-GitHub #1","url":"/#/opensource","externalUrl":"https://github.com/pcodesdev/Git-and-GitHub/pull/1","domain":"open-source","content":"Authored by pcodesdev. Merged pull request in pcodesdev/Git-and-GitHub, created 2023-05-06 and merged 2023-05-07. One file changed with one addition."},{"id":"github-issue-ashutosh1919-masterportfolio-435","title":"Issue: Improve Navigation Accessibility with ARIA Labels #435","url":"/#/opensource","externalUrl":"https://github.com/ashutosh1919/masterPortfolio/issues/435","domain":"open-source","content":"Authored by pcodesdev. Open issue in ashutosh1919/masterPortfolio, created 2026-03-07."},{"id":"github-issue-zero-to-mastery-resources-988","title":"Issue: Product Management and Design New Category #988","url":"/#/opensource","externalUrl":"https://github.com/zero-to-mastery/resources/issues/988","domain":"open-source","content":"Authored by pcodesdev. Closed issue in zero-to-mastery/resources, created 2024-09-12 and closed 2024-09-15."},{"id":"github-issue-maurodesouza-profile-readme-generator-79","title":"Issue: Add latest blog content to README generator #79","url":"/#/opensource","externalUrl":"https://github.com/maurodesouza/profile-readme-generator/issues/79","domain":"open-source","content":"Authored by pcodesdev. Open feature issue in maurodesouza/profile-readme-generator, created 2024-08-31."},{"id":"github-issue-ashutosh1919-masterportfolio-383","title":"Issue: Adopt Responsive Units for Improved Flexibility and Accessibility #383","url":"/#/opensource","externalUrl":"https://github.com/ashutosh1919/masterPortfolio/issues/383","domain":"open-source","content":"Authored by pcodesdev. Open issue in ashutosh1919/masterPortfolio, created 2024-08-18."},{"id":"github-issue-ashutosh1919-masterportfolio-367","title":"Issue: package.json file edit #367","url":"/#/opensource","externalUrl":"https://github.com/ashutosh1919/masterPortfolio/issues/367","domain":"open-source","content":"Authored by pcodesdev. Closed issue in ashutosh1919/masterPortfolio, created 2024-06-20 and closed 2024-06-20."},{"id":"github-issue-vishwugauravin-github-twitter-card-embed-3","title":"Issue: The API is not working #3","url":"/#/opensource","externalUrl":"https://github.com/VishwaGauravIn/github-twitter-card-embed/issues/3","domain":"open-source","content":"Authored by pcodesdev. Closed issue in VishwaGauravIn/github-twitter-card-embed, created 2023-07-23."},{"id":"github-issue-maxovicsteiner-flappy-bird-1","title":"Issue: Site Not Found #1","url":"/#/opensource","externalUrl":"https://github.com/maxovicsteiner/flappy-bird/issues/1","domain":"open-source","content":"Authored by pcodesdev. Closed issue in maxovicsteiner/flappy-bird, created 2023-05-22."},{"id":"github-issue-pcodesdev-git-and-github-2","title":"Issue: Google Authentication #2","url":"/#/opensource","externalUrl":"https://github.com/pcodesdev/Git-and-GitHub/issues/2","domain":"open-source","content":"Authored by pcodesdev. Closed issue in pcodesdev/Git-and-GitHub, created 2023-05-06 and closed 2023-05-07."},{"id":"github-issue-panxproject-awesome-certificates-14","title":"Issue: Industry Recognized Certificates #14","url":"/#/opensource","externalUrl":"https://github.com/PanXProject/awesome-certificates/issues/14","domain":"open-source","content":"Authored by pcodesdev. Closed issue in PanXProject/awesome-certificates, created 2023-04-23 and closed 2023-05-24."},{"id":"github-issue-eddiehubcommunity-support-5394","title":"Issue: GitHub Community Organization invitation #5394","url":"/#/opensource","externalUrl":"https://github.com/EddieHubCommunity/support/issues/5394","domain":"open-source","content":"Authored by pcodesdev. Closed issue in EddieHubCommunity/support, created and closed 2022-09-18."},{"id":"github-issue-kishan0725-hospital-management-system-2","title":"Issue: Admin login problem #2","url":"/#/opensource","externalUrl":"https://github.com/kishan0725/Hospital-Management-System/issues/2","domain":"open-source","content":"Authored by pcodesdev. Closed issue in kishan0725/Hospital-Management-System, created and closed 2021-06-23."},{"id":"github-issue-flutter-flutter-77802","title":"Issue: Flutter VM Service connection delay #77802","url":"/#/opensource","externalUrl":"https://github.com/flutter/flutter/issues/77802","domain":"open-source","content":"Authored by pcodesdev. Closed issue in flutter/flutter, created 2021-03-10 and closed 2021-04-07."},{"id":"contact","title":"Contact and Professional Availability","url":"/#/contact","externalUrl":"mailto:njugunapm23@gmail.com","content":"Peter is open to roles and projects focused on practical implementation, stakeholder coordination, workforce development, digital transformation, digital skills, technology-enabled learning, and software development. Public contact email: njugunapm23@gmail.com. Location: Nairobi, Kenya."}]')}}]);
